STEPS = {"validate": validate, "reserve": reserve, "charge": charge}

def advance(env: Envelope) -> Envelope:
    while env.cursor < len(env.slip):
        step = STEPS.get(env.slip[env.cursor])
        if step is None:
            raise UnknownStep(env.slip[env.cursor])
        env.body = step(env.body)
        env.cursor += 1
    return env
